WITH lines AS (SELECT id, log_ts, latency_ms, status_code, attr_key, value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) x AS attr_key, value) SELECT *, SUM(status_code) OVER w_running AS status_code_sum_1h, COUNT(status_code) OVER w_running AS status_code_count_1h, ROUND(status_code / SUM(status_code) OVER (PARTITION BY attr_key), 4) AS status_code_share, MAX(status_code) OVER (PARTITION BY attr_key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 900 PRECEDING AND CURRENT ROW) AS status_code_max_15m FROM lines WHERE attr_key IN ('trace', 'version') WINDOW w_running AS (PARTITION BY attr_key ORDER BY CAST(log_ts AS BIGINT) RANGE BETWEEN 3600 PRECEDING AND CURRENT ROW)
